/* Optional BC source-art sidecar. The private header is an independently
 * prepared input, never committed or regenerated by this translation unit.
 * The linker retains only the two referenced body frames.
 * Sidecar contract v1: regenerate independently with
 * tools/sc64_bc_body_art.py and an authenticated USA ROM and palette remap.
 * The normal sprite importer and its existing banks remain unchanged. */
#if defined(SC64_BATTLECRUISER_EXPERIMENT) && defined(SC64_ZP_CAMPAIGN_ACTORS) && defined(SC64_HAS_SPRITES)
#include "../.local/sc64/bc-body/sc64_bc_body_art_generated.h"
#if !defined(SC64_BC_BODY_ART_FORMAT_VERSION) || SC64_BC_BODY_ART_FORMAT_VERSION != 1u
#error "BC body sidecar requires format version 1"
#endif
_Static_assert(sizeof(sc64_race_sprite_science_facility_frame_0_pixels)==56u*45u,
               "BC body art v1 science facility size");
_Static_assert(sizeof(sc64_race_sprite_physics_lab_frame_0_pixels)==34u*31u,
               "BC body art v1 physics lab size");
int sc64_bc_body_art(unsigned raw, short *x, short *y, unsigned short *w,
                     unsigned short *h, unsigned short *cw, unsigned short *ch,
                     const unsigned char **pixels)
{
    const Sc64SpriteFrame *s;
    if (raw==116u) s=&sc64_race_sprite_science_facility_frame_0;
    else if (raw==118u) s=&sc64_race_sprite_physics_lab_frame_0;
    else return 0;
    *x=s->offset_x;*y=s->offset_y;*w=s->w;*h=s->h;
    *cw=s->canvas_w;*ch=s->canvas_h;*pixels=s->pixels;
    return 1;
}
#else
typedef int sc64_bc_body_art_disabled;
#endif
